// Lettering in the UI's fourteen-segment face, for a skin that draws its
// text in segments over unlit cells (one that sets Ox.Text.Ghost). A key's
// image is rendered without the UI's bundled fonts, so the glyphs travel as
// outlines: segment-font.json, generated by tools/deck-segments.py, under the
// SIL Open Font License in segment-font-OFL.txt.
import fs from 'node:fs';

const font = JSON.parse(fs.readFileSync(new URL('./segment-font.json', import.meta.url), 'utf8'));
const units = font.unitsPerEm;
const full = font.glyphs[font.full];

// Whether a palette's unlit cells are drawn at all: a colour with no alpha is none.
export function segmented(ghost) {
  return typeof ghost === 'string' && !(ghost.length === 9 && ghost.endsWith('00'));
}

const glyphOf = ch => font.glyphs[ch] ?? null;

// The width of text at a font size, in pixels. A character the face lacks
// keeps a blank cell, as a display would.
export function segmentWidth(text, size) {
  let advance = 0;
  for (const ch of text) advance += glyphOf(ch)?.advance ?? font.cell;
  return advance * size / units;
}

// The largest size, up to `size`, at which text fits in `width` pixels.
export function fittedSize(text, size, width) {
  const at = segmentWidth(text, size);
  return at <= width ? size : size * width / at;
}

const num = v => Math.round(v * 100) / 100;

// SVG for text with its baseline at y, anchored at x ('start', 'middle' or
// 'end'). Each character the face draws as a full cell stands over that
// cell's unlit segments in `ghost`; points and colons and characters the face
// lacks have none. `glow` adds a soft halo of the lettering's own colour,
// drawn from a filter with that id in the image's defs.
export function segmentText(text, x, y, size, {fill, ghost = null, anchor = 'middle', glow = null} = {}) {
  const scale = size / units;
  const width = segmentWidth(text, size);
  let pen = anchor === 'middle' ? x - width / 2 : anchor === 'end' ? x - width : x;
  let cells = '', lit = '';
  for (const ch of text) {
    const glyph = glyphOf(ch);
    const at = `translate(${num(pen)} ${num(y)}) scale(${num(scale * 1000) / 1000} ${-num(scale * 1000) / 1000})`;
    if (glyph && glyph.advance === font.cell && ghost && ch !== '.' && ch !== ':')
      cells += `<path transform="${at}" d="${full.path}"/>`;
    if (glyph?.path) lit += `<path transform="${at}" d="${glyph.path}"/>`;
    pen += (glyph?.advance ?? font.cell) * scale;
  }
  return (cells ? `<g fill="${ghost}">${cells}</g>` : '') +
    (glow && lit ? `<g fill="${fill}" filter="url(#${glow})" opacity="0.7">${lit}</g>` : '') +
    (lit ? `<g fill="${fill}">${lit}</g>` : '');
}
